import { expect, type Page, test } from '@playwright/test';

// Snow parks (generated by the pipeline inside OSM snow_park areas) and floodlit runs.
const RESORT = 'resort=les-3-vallees';

interface Feature {
  kind: string;
  east: number;
  north: number;
  heading: number;
}
interface SkiHandle {
  velocity: { clone(): { set(x: number, y: number, z: number): unknown } };
  place(pose: object, velocity: unknown): void;
  airborne: boolean;
  lastLanding: { outcome: string } | null;
  feet: { x: number; y: number; z: number };
  onRail: boolean;
}

async function start(page: Page, query: string) {
  await page.addInitScript(() => {
    Object.defineProperty(Document.prototype, 'pointerLockElement', {
      get: () => document.querySelector('#scene'),
    });
  });
  await page.goto(`/?${RESORT}&${query}`);
  await page.waitForFunction(() => (window.__sim?.frames ?? 0) > 10, null, { timeout: 90_000 });
  await page.evaluate(() => document.dispatchEvent(new Event('pointerlockchange')));
}

/** The first kicker of the named park, from the build's pistes.json. */
async function kicker(page: Page, park: string): Promise<Feature> {
  return page.evaluate(async (park) => {
    const data = await (await fetch('/les-3-vallees/pistes.json')).json();
    const index = data.pistes.find((p: { name: string }) => p.name === park).index;
    const layout = data.parks.find((p: { index: number }) => p.index === index);
    return layout.features.find((f: Feature) => f.kind === 'kicker');
  }, park);
}

test('skiing into a kicker launches you off the lip and you land on the snow', async ({ page }) => {
  // Anywhere first; the skier is then placed 25 m above a VT Park kicker.
  await start(page, 'at=45.27692,6.57690,2600&heading=315&pitch=-10');
  const k = await kicker(page, 'VT Park');
  await page.keyboard.press('KeyF'); // ski mode
  await page.keyboard.press('KeyV'); // chase camera, to see the air
  const rad = (k.heading * Math.PI) / 180;
  await page.evaluate(
    ([k, rad]) => {
      const ski = (window.__sim as unknown as { ski: SkiHandle }).ski;
      const [s, c] = [Math.sin(rad), Math.cos(rad)];
      const east = k.east - 25 * s;
      const north = k.north - 25 * c;
      const pose = { east, north, altitude: 0, heading: k.heading, pitch: -10 };
      ski.place(pose, ski.velocity.clone().set(9 * s, 0, -9 * c));
    },
    [k, rad] as const,
  );
  // Airborne within a few seconds, close to the lip.
  await page.waitForFunction(
    () => (window.__sim as unknown as { ski: SkiHandle }).ski.airborne,
    null,
    { timeout: 8000 },
  );
  const takeoff = await page.evaluate(() => {
    const f = (window.__sim as unknown as { ski: SkiHandle }).ski.feet;
    return { east: f.x, north: -f.z };
  });
  const fromLip = Math.hypot(takeoff.east - k.east, takeoff.north - k.north);
  expect(fromLip).toBeLessThan(4);
  await page.waitForTimeout(250);
  await page.screenshot({ path: 'test-results/views/park-kicker-air.png' });

  await page.waitForFunction(() => {
    const ski = (window.__sim as unknown as { ski: SkiHandle }).ski;
    return !ski.airborne && ski.lastLanding;
  });
  const landing = await page.evaluate(
    () => (window.__sim as unknown as { ski: SkiHandle }).ski.lastLanding!,
  );
  expect(landing.outcome).not.toBe('crash');
  await expect(page.locator('#run [data-piste] span')).toHaveText('VT Park');
});

test('a rail boardslides: skis across it, it barely slows you and keeps you on it', async ({
  page,
}) => {
  await start(page, 'at=45.27692,6.57690,2600&heading=315&pitch=-10');
  const rail = await page.evaluate(async () => {
    const data = await (await fetch('/les-3-vallees/pistes.json')).json();
    const rails = data.parks.flatMap((p: { features: Feature[] }) =>
      p.features.filter((f) => f.kind === 'box'),
    );
    return rails[0] as Feature & { profile: [number, number][] };
  });
  await page.keyboard.press('KeyF'); // ski mode
  await page.keyboard.press('KeyV'); // chase camera
  const rad = (rail.heading * Math.PI) / 180;
  // Dropped onto the start of the rail at 7 m/s along it, skis across it, a little off centre.
  await page.evaluate(
    ([r, rad]) => {
      const ski = (window.__sim as unknown as { ski: SkiHandle }).ski;
      const [s, c] = [Math.sin(rad), Math.cos(rad)];
      const pose = {
        east: r.east + 1 * s - 0.15 * c,
        north: r.north + 1 * c + 0.15 * s,
        altitude: 0,
        heading: r.heading + 90,
        pitch: -10,
      };
      ski.place(pose, ski.velocity.clone().set(7 * s, 0, -7 * c));
    },
    [rail, rad] as const,
  );
  const samples: { onRail: boolean; along: number; across: number; speed: number }[] = [];
  for (let i = 0; i < 12; i++) {
    samples.push(
      await page.evaluate(
        ([r, rad]) => {
          const sim = window.__sim as unknown as {
            ski: SkiHandle & { velocity: { length(): number } };
          };
          const f = sim.ski.feet;
          const [de, dn] = [f.x - r.east, -f.z - r.north];
          const [s, c] = [Math.sin(rad), Math.cos(rad)];
          return {
            onRail: sim.ski.onRail,
            along: de * s + dn * c,
            across: -de * c + dn * s,
            speed: sim.ski.velocity.length(),
          };
        },
        [rail, rad] as const,
      ),
    );
    if (i === 3) await page.screenshot({ path: 'test-results/views/park-rail-slide.png' });
    if (!samples.at(-1)!.onRail && i > 0) break;
    await page.waitForTimeout(100);
  }
  const sliding = samples.filter((s) => s.onRail);
  expect(sliding.length).toBeGreaterThan(3);
  // Centred, and still quick (a hockey stop on snow would have stopped you by now).
  expect(Math.abs(sliding.at(-1)!.across)).toBeLessThan(0.1);
  expect(Math.min(...sliding.map((s) => s.speed))).toBeGreaterThan(6);
  // Off the far end, not the side.
  const end = rail.profile.at(-1)![0];
  expect(samples.at(-1)!.along).toBeGreaterThan(end - 1.5);
});

test('park features render from the side', async ({ page }) => {
  const errors: string[] = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
  await page.goto(`/?${RESORT}&at=45.27730,6.57672,2580&heading=225&pitch=-8`);
  await page.waitForFunction(() => (window.__sim?.frames ?? 0) > 30, null, { timeout: 90_000 });
  await page.evaluate(() => document.body.classList.add('flying'));
  await page.waitForTimeout(500);
  await page.screenshot({ path: 'test-results/views/park-kicker-side.png' });
  // The boardercross: berms and rollers.
  await page.goto(`/?${RESORT}&at=45.3470,6.5785,2310&heading=20&pitch=-45`);
  await page.waitForFunction(() => (window.__sim?.frames ?? 0) > 30, null, { timeout: 90_000 });
  await page.evaluate(() => document.body.classList.add('flying'));
  await page.waitForTimeout(500);
  await page.screenshot({ path: 'test-results/views/park-boardercross.png' });
  expect(errors).toEqual([]);
});

test('floodlit runs glow at night', async ({ page }) => {
  // 21:00, clock paused: the floodlights on the Verdons runs (Courchevel) are on.
  await page.addInitScript(() =>
    localStorage.setItem('ski-sim.time-of-day', JSON.stringify({ seconds: 75600, rate: 0 })),
  );
  await page.goto(`/?${RESORT}&at=45.3955,6.6180,2110&heading=45&pitch=-15`);
  await page.waitForFunction(() => (window.__sim?.frames ?? 0) > 30, null, { timeout: 90_000 });
  await page.evaluate(() => document.body.classList.add('flying'));
  await page.waitForTimeout(500);
  const shot = await page.screenshot({ path: 'test-results/views/floodlit-night.png' });
  // Warm light on the snow: some bright, orange-ish pixels in an otherwise dark frame.
  const glow = await page.evaluate(async (png) => {
    const bitmap = await createImageBitmap(new Blob([new Uint8Array(png)], { type: 'image/png' }));
    const canvas = new OffscreenCanvas(bitmap.width, bitmap.height);
    const ctx = canvas.getContext('2d')!;
    ctx.drawImage(bitmap, 0, 0);
    const { data } = ctx.getImageData(0, bitmap.height * 0.4, bitmap.width, bitmap.height * 0.3);
    let warm = 0;
    for (let i = 0; i < data.length; i += 4) {
      if (data[i]! > 110 && data[i]! > data[i + 2]! + 25) warm++;
    }
    return warm;
  }, Array.from(shot));
  expect(glow).toBeGreaterThan(800);
});
